/**
 * The KeyboardAvoidingView behaviour for this screen: 'padding' while a
 * keyboard is up, none once it is gone. Android reports a closed keyboard's top
 * edge above the system bars on an edge-to-edge window, and the view kept that
 * gap as padding after every keyboard; dropping the behaviour clears it.
 */
export function useKeyboardBehavior(): 'padding' | undefined {
  const [shown, setShown] = useState(false);
  useEffect(() => {
    if (Platform.OS === 'ios') return undefined;
    const up = Keyboard.addListener('keyboardDidShow', () => setShown(true));
    const down = Keyboard.addListener('keyboardDidHide', () => setShown(false));
    return () => {
      up.remove();
      down.remove();
    };
  }, []);
  return Platform.OS === 'ios' || shown ? 'padding' : undefined;
}

/**
 * How far a widget pinned to the bottom of the window rises while a keyboard is
 * up, 0 once it is gone: the window does not shrink for the keyboard (edge to
 * edge on Android, an overlay on iOS), so a pinned CTA stayed under it and the
 * form could not be sent without closing the keyboard first. The widget's own
 * gap already clears the bottom inset, so the rise is the keyboard's reach
 * ABOVE that inset. iOS measures the keyboard from the screen's edge, the
 * home-indicator band included, so the inset comes off; Android measures it
 * above the system bars already, and taking the nav bar off a second time left
 * the CTA under the keyboard on a phone with buttons. A hide is never
 * measured, for the reason above.
 */
export function useKeyboardLift(bottomInset: number): number {
  const [height, setHeight] = useState(0);
  useEffect(() => {
    const ios = Platform.OS === 'ios';
    const up = Keyboard.addListener(ios ? 'keyboardWillShow' : 'keyboardDidShow', (e) =>
      setHeight(e.endCoordinates.height),
    );
    const down = Keyboard.addListener(ios ? 'keyboardWillHide' : 'keyboardDidHide', () =>
      setHeight(0),
    );
    return () => {
      up.remove();
      down.remove();
    };
  }, []);
  return Platform.OS === 'ios' ? Math.max(0, height - bottomInset) : height;
}

