/** Keeps a screen that shows an `until` countdown moving: once a second, and only while one was drawn. */
export function useUntilTick(): void {
  const [, tick] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => {
    const timer = setInterval(() => {
      if (takeUntilSeen()) tick();
    }, 1000);
    return () => clearInterval(timer);
  }, []);
}

