/**
 * The same bundle for a screen that WRITES fields without reading any.
 *
 * It exists only to leave out the `values` subscription. A screen that just
 * captures input — a passcode entry, an OTP box — reads nothing back, and
 * subscribing it to the store means every keystroke on it, and every write from
 * any other mounted screen, re-renders the whole thing and recomputes every
 * s()/sv() length. The return type OMITS values rather than handing back an
 * empty map, so a screen that turns out to need them fails to compile instead
 * of quietly rendering blanks.
 */
export function useScreenFormWriter(): Omit<ScreenForm, 'values'> {
  return useFormRest();
}

/**
 * The screen-LOCAL half of the bundle, for a subtree that was hoisted out of
 * the screen into its own component.
 *
 * The form VALUES are app-level, so a hoisted subtree reads them straight from
 * the store. Two things are not: the validation messages (a useState belonging
 * to the screen being validated) and the field-scroll handle (bound to THAT
 * screen's scroller, which is what makes scroll-to-first-error land in the
 * right place). Extraction used to be refused for any subtree naming either —
 * which kept every validated input inline, and a design with a family of
 * near-identical form screens then emitted the same field block on each of
 * them. Passing the two down as context is what makes those hoistable.
 */
/**
 * The half a hoisted subtree cannot get for itself. The form VALUES are not
 * here: they are app-level, so a hoisted subtree reads them from the store
 * directly. Typing the provider to this rather than to the whole bundle is also
 * what lets a write-only screen publish one — it has no values to give.
 */
export type ScreenFormBinding = Pick<ScreenForm, 'errors' | 'fieldScroll' | 'setField'>;

const ScreenFormContext = React.createContext<ScreenFormBinding | null>(null);

export function ScreenFormProvider({
  form,
  children,
}: Readonly<{ form: ScreenFormBinding; children?: React.ReactNode }>) {
  return <ScreenFormContext.Provider value={form}>{children}</ScreenFormContext.Provider>;
}

const NO_ERRORS: Record<string, string> = {};
const NO_SCROLL: ReturnType<typeof useFieldScroll> = {
  scrollProps: { ref: () => undefined, onScroll: () => undefined, scrollEventThrottle: 16 },
  bind: () => () => undefined,
};

/**
 * setField travels with the binding so there is exactly ONE of it.
 *
 * A hoisted field used to be handed a second, synthesised setField that wrote
 * the value and nothing else. The screen's own also DELETES that field's stale
 * error — which is what makes a validation message disappear when the user
 * fixes the field. With two implementations, a hoisted input showed its error
 * once and then kept it for the life of the mount: retyping did not clear it,
 * and neither did a later successful submit, because the submit path only ever
 * merges errors in. The red border and any layout shift keyed off the message
 * became permanent.
 */
const fallbackSetField = (k: string, v: unknown): void => {
  // getState(), not the hook: this path has no provider and therefore no screen
  // to re-render on a subscription
  useFormStore.getState().setValues((s0) => ({ ...s0, [k]: v }));
};

/**
 * Deliberately NOT a throw when there is no provider: a shared component is
 * also rendered by the design system page and by tests, and a hoisted field
 * that crashes outside a screen would be a worse bargain than one that renders
 * without its error text. It degrades to no message and no scroll binding —
 * the write itself still works.
 */
export function useScreenFormBinding(): ScreenFormBinding {
  return (
    React.useContext(ScreenFormContext) ?? {
      errors: NO_ERRORS,
      fieldScroll: NO_SCROLL,
      setField: fallbackSetField,
    }
  );
}

/**
 * A press handler, or NOTHING while the control is gated.
 *
 * A generated CTA is live only when its timer edge has fired, its form is
 * valid and nothing it triggers is in flight — and the screens spelled that
 * out as `gate && ready && !busy ? handler : undefined` right in the JSX, once
 * per button. Behaviour is identical; what moves out of the screen is the
 * conditional.
 */
export function pressWhen<T>(enabled: boolean, handler: T): T | undefined {
  return enabled ? handler : undefined;
}

/** The same gate stated negatively — `!x ? a : b` is a finding of its own
 * (Sonar S7735), so a single-term gate is emitted this way round instead. */
export function pressUnless<T>(blocked: boolean, handler: T): T | undefined {
  return blocked ? undefined : handler;
}

/**
 * A STATE'S tint, as a spread and as a bare value.
 *
 * A design's selected chip, its ready button and its error text all say the
 * same thing — "this colour, but only while X" — and the screens spelled that
 * out inline: `...(X ? { color: '#…' } : {})` on every themable text and
 * `X ? '#…' : undefined` on every tinted glyph. A seven-option choice group
 * carries fourteen of them, and they were most of that screen's cognitive
 * complexity for a question with one answer. The condition is tested for its
 * truth (a message held by `apiError` counts), like pxUnless.
 */
export function tintWhen(on: unknown, color: string): { color?: string } {
  return on ? { color } : {};
}

/** The same, where the consumer wants the colour itself (Image tintColor). */
export function colorWhen(on: unknown, color: string): string | undefined {
  return on ? color : undefined;
}

/** Full strength while the condition holds, dimmed to `dim` otherwise — how a
 * generated screen shows a control that is present but not yet usable. */
export function opacityWhen(on: unknown, dim: number): number {
  return on ? 1 : dim;
}

/**
 * The rows a repeat section renders.
 *
 * The implicit first row is `{ id: 'r0' }`, and it has to be the SAME seed for
 * every reader: the row map, the remove filter, the request mapping and the
 * three offset sums all derive from it. They used to derive it separately, from
 * one expression the emitters inlined at each site — a screen with one repeat
 * section carried fifteen copies of it. Any drift between them looked exactly
 * like the bug it caused when the seed was missing: a row that renders but
 * cannot be deleted, or a section whose height stops matching its content.
 *
 * One function also keeps that logic OUT of the screen component, where fifteen
 * inlined `&&` + ternary pairs were most of its cognitive complexity.
 */
export function rowsOf(values: FormStore['values'], key: string): unknown[] {
  const v = values[key];
  return Array.isArray(v) && v.length > 0 ? (v as unknown[]) : [{ id: 'r0' }];
}

/**
 * The id of a row, as the map key and the per-row field suffix both spell it.
 *
 * NARROWED, not stringified blind. Every reader used to inline
 * `String((__r as { id?: unknown })?.id ?? '')` — 53 of them on one app — and
 * String() over an `unknown` turns an object into "[object Object]" (Sonar
 * S6551), which as a row key means two rows collide and one of them cannot be
 * removed. Only a string or a number is a usable id; anything else falls back
 * to the map index, which is what the row map keys off anyway.
 */
export function ridOf(row: unknown, fallbackIndex?: number): string {
  const id = (row as { id?: unknown })?.id;
  if (typeof id === 'string') return id;
  if (typeof id === 'number') return String(id);
  return fallbackIndex === undefined ? '' : String(fallbackIndex);
}

/**
 * Row ids are unique within this process, which is all a list key needs.
 *
 * NOT Math.random(): Sonar flags a PRNG wherever a CSPRNG might have been meant
 * (S2245), and the flag is fair — Hermes seeds Math.random per process, so two
 * relaunches can draw the same sequence. A counter cannot repeat at all.
 */
let rowSeq = 0;
function newRowId(): string {
  rowSeq += 1;
  return 'r' + Date.now().toString(36) + rowSeq.toString(36);
}

/** Append a row, honouring the design's `[repeat max=n]` cap when it set one. */
export function addRow(
  values: FormStore['values'],
  setField: (k: string, v: unknown) => void,
  key: string,
  max?: number,
): void {
  const rows = rowsOf(values, key);
  if (max !== undefined && rows.length >= max) return;
  const id = newRowId();
  setField(key, [...rows, { id }]);
  // ...and the row it adds is the one open, where a section shows one row open (isOpenRow)
  setField(openKeyOf(key), id);
}

/**
 * Form-state key holding the row a section shows open: a row's Edit (openRow)
 * and Add set it. Mirrors openRowKey in the designer's render/fieldkey.ts.
 */
function openKeyOf(key: string): string {
  return 'open:' + key;
}

/** The open row a section's Done leaves: none, every row as its summary until an Edit or Add opens one. */
const NO_ROW_OPEN = 'none';

/**
 * Is this the section's open row: the one Edit or Add opened, else the last,
 * and none after a Done. A section can show one row open and the rest as their
 * summaries (an invoice's items, edited one at a time). Mirrors isOpenRow in
 * the designer's render/fieldkey.ts.
 */
export function isOpenRow(values: FormStore['values'], key: string, rid: string): boolean {
  const open = values[openKeyOf(key)];
  if (open === NO_ROW_OPEN) return false;
  const ids = rowsOf(values, key).map((r, i) => ridOf(r, i));
  const at = typeof open === 'string' && ids.includes(open) ? open : ids.at(-1);
  return at === rid;
}

/** Show this row open: a row's Edit. */
export function openRow(setField: (k: string, v: unknown) => void, key: string, rid: string): void {
  setField(openKeyOf(key), rid);
}

/** Show no row open: a row's Done folds it into its summary with the rest. */
export function closeRows(setField: (k: string, v: unknown) => void, key: string): void {
  setField(openKeyOf(key), NO_ROW_OPEN);
}

/** A field's number, or NaN: a blank field holds no number (it is not 0). */
function numOf(v: unknown): number {
  if (typeof v === 'number') return v;
  const s = typeof v === 'string' ? v.trim() : '';
  return s === '' ? Number.NaN : Number(s);
}

/** Two values multiplied (a row's quantity and price): blank unless both are numbers, never NaN on screen. */
export function product(a: unknown, b: unknown): string {
  const n = numOf(a) * numOf(b);
  return Number.isFinite(n) ? String(n) : '';
}

/**
 * A repeat section's rows added up: each row's fields multiplied together (one
 * field: that field alone). A row with a blank field adds nothing. An
 * invoice's subtotal over its item rows (quantity times price).
 */
/**
 * A row's field as a number, a blank one taking the default its spec names: 'qty=1' counts a quantity left empty as
 * 1, as the row's own line total does. Mirrors rowFactor in the designer's run/appRead.ts.
 */
function rowFactor(values: FormStore['values'], spec: string, rid: string): number {
  const at = spec.indexOf('=');
  const raw = values[(at < 0 ? spec : spec.slice(0, at)) + '#' + rid];
  const blank = raw == null || (typeof raw === 'string' && raw.trim() === '');
  return blank && at >= 0 ? numOf(spec.slice(at + 1)) : numOf(raw);
}

export function sumRows(values: FormStore['values'], key: string, fields: string[]): string {
  let total = 0;
  for (const row of rowsOf(values, key)) {
    const rid = ridOf(row);
    const n = fields.reduce((acc, f) => acc * rowFactor(values, f, rid), 1);
    if (Number.isFinite(n)) total += n;
  }
  return String(total);
}

/** Remove a row BY ID — never the last one, or the section would vanish. */
export function removeRow(
  values: FormStore['values'],
  setField: (k: string, v: unknown) => void,
  key: string,
  rid: string,
): void {
  const rows = rowsOf(values, key);
  if (rows.length > 1)
    setField(
      key,
      rows.filter((r) => ridOf(r) !== rid),
    );
}
